test(
  'native retained admission previews existing controllers and recreated hooks without changing live resources',
  { timeout: 30000 },
  async (t) => {
    const folder = await fs.mkdtemp(path.join(os.tmpdir(), 'rivet-retained-admission-'));
    t.after(() => fs.rm(folder, { recursive: true, force: true }));
    const ns = 'retained-fixture',
      release = 'rivet';
    const workload = (kind, name) => ({
      apiVersion: kind === 'Job' ? 'batch/v1' : 'apps/v1',
      kind,
      metadata: {
        name,
        namespace: ns,
        labels: { 'app.kubernetes.io/instance': release },
        ...(kind === 'Job'
          ? { annotations: { 'helm.sh/hook-delete-policy': 'before-hook-creation,hook-succeeded' } }
          : {}),
      },
      spec: {
        selector: { matchLabels: { app: name } },
        template: {
          metadata: { labels: { app: name } },
          spec: {
            containers: [
              {
                name: 'app',
                image: 'registry.test/app:fixture',
                resources: { requests: { cpu: '50m', memory: '128Mi' } },
              },
            ],
          },
        },
      },
    });
    const desired = [
      workload('Deployment', 'web'),
      workload('StatefulSet', 'execution'),
      workload('Job', 'migration'),
      workload('StatefulSet', 'execution-next'),
    ];
    const methods = [],
      errors = [];
    const f = await fixture(t, providerOperation(), {
      intercept(packet) {
        try {
          assertFixtureRequest(packet.req);
          if (cliDiscovery(packet)) return true;
          const { req, url, input, objects, res, result } = packet;
          if (url.searchParams.get('dryRun') === 'All') {
            assert.ok(['POST', 'PUT'].includes(req.method));
            const existing = objects.get(
              req.method === 'POST' ? url.pathname + '/' + input.metadata.name : url.pathname,
            );
            if (req.method === 'POST') {
              assert.ok(!existing, 'A dry-run create on an existing object fails AlreadyExists');
              res.statusCode = 201;
            } else {
              assert.ok(existing && input.kind !== 'Job');
              assert.equal(input.metadata.uid, existing.metadata.uid);
              assert.equal(input.metadata.resourceVersion, existing.metadata.resourceVersion);
              assert.deepEqual(input.spec.selector, existing.spec.selector);
            }
            methods.push({ method: req.method, kind: input.kind, name: input.metadata.name });
            const admitted = structuredClone(input);
            admitted.spec.template.spec.containers[0].resources.requests.cpu = '500m';
            result(admitted);
            return true;
          }
          return nativeKubernetes(packet);
        } catch (error) {
          errors.push(error);
          packet.res.statusCode = 500;
          packet.result({ message: error.message });
          return true;
        }
      },
    });
    f.store(`/api/v1/namespaces/${ns}`, { apiVersion: 'v1', kind: 'Namespace', metadata: { name: ns } });
    for (const resource of desired.slice(0, 3)) {
      const api = resource.kind === 'Job' ? '/apis/batch/v1' : '/apis/apps/v1';
      f.store(`${api}/namespaces/${ns}/${resource.kind.toLowerCase()}s/${resource.metadata.name}`, resource);
    }
    const before = JSON.stringify([...f.objects]);
    const kubeconfig = path.join(folder, 'kubeconfig.json');
    await fs.writeFile(
      kubeconfig,
      JSON.stringify({
        apiVersion: 'v1',
        kind: 'Config',
        clusters: [{ name: 'local', cluster: { server: f.origin } }],
        users: [],
        contexts: [{ name: 'local', context: { cluster: 'local', namespace: ns } }],
        'current-context': 'local',
      }),
    );
    const gate = {
      config: { namespace: ns, release },
      state: { application: {} },
      resources: async () => structuredClone(desired),
      artifact: async () => {},
      kube: (args, options = {}) =>
        run(process.env.RIVET_K8S_KUBECTL_BIN || 'kubectl', ['--kubeconfig', kubeconfig, '--namespace', ns, ...args], {
          capture: true,
          ...options,
        }),
    };
    await ReusableProviderGate.prototype.verifyAdmission.call(gate, {});
    assert.deepEqual(errors, []);
    assert.equal(methods.filter((entry) => entry.method === 'PUT').length, 2);
    assert.equal(methods.filter((entry) => entry.method === 'POST').length, 2);
    assert.match(methods.find((entry) => entry.kind === 'Job').name, /^migration-dry-/);
    assert.equal(JSON.stringify([...f.objects]), before, 'All admission operations must remain dry runs');
  },
);

test(
  'native Helm keeps the migration hook blocking when ordinary template readiness is deferred',
  { timeout: 30000 },
  async (t) => {
    for (const scenario of ['overlap', 'failed-hook', 'blocking-default'])
      await t.test(scenario, async (t) => {
        const folder = await fs.mkdtemp(path.join(os.tmpdir(), 'rivet-helm-readiness-'));
        t.after(() => fs.rm(folder, { recursive: true, force: true }));
        const watched = Promise.withResolvers();
        let watch;
        const f = await fixture(t, operation(), {
          decodeBody: decodeKubernetesBody,
          intercept(packet) {
            assertFixtureRequest(packet.req);
            if (cliDiscovery(packet)) return true;
            const { req, res, url, objects } = packet;
            if (
              req.method === 'GET' &&
              url.pathname.endsWith('/jobs') &&
              ['1', 'true'].includes(url.searchParams.get('watch'))
            ) {
              watch = res;
              res.setHeader('content-type', 'application/json');
              const job = [...objects.values()].find((resource) => resource.kind === 'Job');
              res.write(JSON.stringify({ type: 'ADDED', object: job }) + '\n');
              if (url.searchParams.get('sendInitialEvents') === 'true')
                res.write(
                  JSON.stringify({
                    type: 'BOOKMARK',
                    object: {
                      apiVersion: 'batch/v1',
                      kind: 'Job',
                      metadata: {
                        resourceVersion: job.metadata.resourceVersion,
                        annotations: { 'k8s.io/initial-events-end': 'true' },
                      },
                    },
                  }) + '\n',
                );
              watched.resolve();
              return true;
            }
            const handled = nativeKubernetes(packet);
            if (handled && req.method === 'POST' && packet.input?.kind === 'Job')
              objects.get(url.pathname + '/' + packet.input.metadata.name).status = {};
            if (handled && req.method === 'POST' && packet.input?.kind === 'Deployment')
              for (const resource of objects.values()) {
                if (resource.kind === 'Deployment')
                  resource.status.readyReplicas = resource.status.availableReplicas = 0;
                if (resource.kind === 'ReplicaSet') resource.status.readyReplicas = 0;
                if (resource.kind === 'Pod') resource.status.conditions = [{ type: 'Ready', status: 'False' }];
              }
            return handled;
          },
        });
        f.store('/api/v1/namespaces/fixture', { apiVersion: 'v1', kind: 'Namespace', metadata: { name: 'fixture' } });
        const kubeconfig = path.join(folder, 'kubeconfig.json');
        await fs.writeFile(
          kubeconfig,
          JSON.stringify({
            apiVersion: 'v1',
            kind: 'Config',
            clusters: [{ name: 'local', cluster: { server: f.origin } }],
            users: [],
            contexts: [{ name: 'local', context: { cluster: 'local', namespace: 'fixture' } }],
            'current-context': 'local',
          }),
        );
        const chart = path.join(folder, 'chart');
        await fs.mkdir(path.join(chart, 'templates'), { recursive: true });
        await fs.writeFile(path.join(chart, 'Chart.yaml'), 'apiVersion: v2\nname: fixture\nversion: 0.1.0\n');
        const args = [
          'upgrade',
          '--install',
          'readiness',
          chart,
          '--namespace',
          'fixture',
          '--kubeconfig',
          kubeconfig,
          '--disable-openapi-validation',
          '--timeout',
          '3s',
        ];
        const env = {
          ...process.env,
          KUBECONFIG: kubeconfig,
          HELM_CACHE_HOME: path.join(folder, 'cache'),
          HELM_CONFIG_HOME: path.join(folder, 'config'),
          HELM_DATA_HOME: path.join(folder, 'data'),
        };
        const helm = process.env.RIVET_K8S_HELM_BIN || 'helm';
        await run(helm, args, { capture: true, env });
        await fs.writeFile(
          path.join(chart, 'templates/hook.json'),
          JSON.stringify({
            apiVersion: 'batch/v1',
            kind: 'Job',
            metadata: { name: 'migration', annotations: { 'helm.sh/hook': 'pre-upgrade' } },
            spec: {
              backoffLimit: 0,
              template: {
                spec: {
                  restartPolicy: 'Never',
                  containers: [{ name: 'migration', image: 'fixture.invalid/migration:local' }],
                },
              },
            },
          }),
        );
        await fs.writeFile(
          path.join(chart, 'templates/proxy.json'),
          JSON.stringify({
            apiVersion: 'apps/v1',
            kind: 'Deployment',
            metadata: { name: 'proxy' },
            spec: {
              replicas: 1,
              selector: { matchLabels: { app: 'proxy' } },
              template: {
                metadata: { labels: { app: 'proxy' } },
                spec: { containers: [{ name: 'proxy', image: 'fixture.invalid/proxy:local' }] },
              },
            },
          }),
        );
        const outcome = run(
          helm,
          [...args, ...(scenario === 'blocking-default' ? ['--wait', '--wait-for-jobs'] : [])],
          { capture: true, env },
        ).then(
          (value) => ({ value }),
          (error) => ({ error }),
        );
        try {
          const early = await Promise.race([watched.promise.then(() => null), outcome]);
          assert.equal(early, null, early?.error?.message);
          assert.ok(
            !f.requests.some((request) => request.method === 'POST' && request.pathname.endsWith('/deployments')),
            'Migration must finish before frontend mutation',
          );
          const job = f.objects.get('/apis/batch/v1/namespaces/fixture/jobs/migration');
          job.status =
            scenario === 'failed-hook'
              ? { failed: 1, conditions: [{ type: 'Failed', status: 'True', reason: 'BackoffLimitExceeded' }] }
              : { succeeded: 1, conditions: [{ type: 'Complete', status: 'True' }] };
          watch.end(JSON.stringify({ type: 'MODIFIED', object: job }) + '\n');
          const result = await outcome;
          if (scenario === 'overlap') assert.ok(!result.error, result.error?.message);
          else assert.ok(result.error, 'A failed hook or unfinished frontend must still fail its owning command');
          const writes = f.requests.filter(
            (request) => request.method === 'POST' && request.pathname.endsWith('/deployments'),
          );
          assert.equal(writes.length, scenario === 'failed-hook' ? 0 : 1);
          assert.equal(
            f.objects.get('/apis/apps/v1/namespaces/fixture/deployments/proxy')?.status.readyReplicas,
            scenario === 'failed-hook' ? undefined : 0,
          );
        } finally {
          watch?.end();
          await outcome;
        }
      });
  },
);

function providerOperation() {
  const make = (letter, predecessorRelease) =>
    createStudioServerReleaseManifest({
      rootDir,
      source: { repository: 'example/rivet', ref: 'refs/heads/main', sha: letter.repeat(40) },
      images: Object.fromEntries(
        ['proxy', 'web', 'api', 'executor'].map((role) => [
          role,
          { repository: `registry.test/${role}`, digest: `sha256:${letter.repeat(64)}` },
        ]),
      ),
      candidateEvidence: evidence,
      predecessorRelease,
    });
  const previous = promoteStudioServerReleaseManifest(make('a'), { promotionEvidence: evidence });
  const { inputHash, ...input } = operation();
  Object.assign(input, {
    previous,
    candidate: make('b', previous),
    qualification: { tier: 'focused' },
    executionPools: true,
    requestContinuityProfile: continuityFixtureProfile,
    startedAt: new Date().toISOString(),
    installed: {
      qualificationValues: {
        requestContinuity: {
          enabled: true,
          maxProtectedRequestSeconds: 300,
          backendServiceDrainSeconds: 360,
          propagationSeconds: 60,
        },
        lifecycle: { proxy: { preStopDelaySeconds: 420, terminationGracePeriodSeconds: 600 } },
        availability: {
          gkeGateway: true,
          gkeGatewayProfile: 'compact',
          podAntiAffinity: { enabled: true, required: true, topologyKey: 'kubernetes.io/hostname' },
          topologySpread: {
            enabled: true,
            topologyKey: 'topology.kubernetes.io/zone',
            nodeTaintsPolicy: 'Honor',
            whenUnsatisfiable: 'DoNotSchedule',
            maxSkew: 1,
            minDomains: 2,
          },
        },
        resources: {
          web: { requests: { cpu: '50m', memory: '128Mi' } },
          proxy: { requests: { cpu: '100m', memory: '128Mi' } },
        },
        postgres: { maxConnections: 250, reservedConnections: 30, poolMaxPerApiPod: 10 },
        legacyRestore: { enabled: true, size: '8Gi' },
      },
    },
  });
  return { ...input, inputHash: qualificationHash(input) };
}

for (const fault of ['none', 'admission', 'lost-ack', 'interrupt'])
  test(`packaged provider preparation and cleanup with native tools: ${fault}`, { timeout: 45000 }, async (t) => {
    const folder = await fs.mkdtemp(path.join(os.tmpdir(), 'rivet-provider-tools-'));
    t.after(() => fs.rm(folder, { recursive: true, force: true }));
    const previousEnv = process.env.KUBECONFIG;
    t.after(() => (previousEnv === undefined ? delete process.env.KUBECONFIG : (process.env.KUBECONFIG = previousEnv)));
    const previousCapture = process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT;
    process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT = '1';
    t.after(() =>
      previousCapture === undefined
        ? delete process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT
        : (process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT = previousCapture),
    );
    const op = providerOperation();
    const errors = [],
      admitted = [];
    const cancellation = new AbortController();
    let faultRequests = 0;
    const namespace = `rivet-staging-${op.operationId}`;
    const computePrefix = `projects/${settings().projectId}`;
    const backendPath = `${computePrefix}/regions/europe-central2/backendServices/fixture`;
    const healthPath = `${computePrefix}/global/healthChecks/fixture`;
    const selfLink = (resource) => `https://compute.googleapis.com/compute/v1/${resource}`;
    const computeObjects = new Map();
    const computeObject = (resource) => {
      if (!computeObjects.has(resource))
        computeObjects.set(resource, {
          id: String(100 + computeObjects.size),
          selfLink: selfLink(resource),
          creationTimestamp: new Date().toISOString(),
          ...(resource === backendPath
            ? {
                healthChecks: [selfLink(healthPath)],
                backends: ['a', 'b'].map((zone) => ({
                  group: selfLink(`${computePrefix}/zones/europe-central2-${zone}/networkEndpointGroups/fixture-neg`),
                })),
              }
            : {}),
        });
      return computeObjects.get(resource);
    };
    const f = await fixture(t, op, {
      decodeBody: decodeKubernetesBody,
      intercept(packet) {
        try {
          assertFixtureRequest(packet.req);
          if (packet.url.pathname.startsWith('/fixture-compute/')) {
            const { res, result, objects, url } = packet;
            if (!objects.has(`/api/v1/namespaces/${namespace}`)) {
              res.statusCode = 404;
              result({});
              return true;
            }
            const resource = url.pathname.split('/compute/v1/')[1];
            result(
              resource.endsWith('/aggregated/backendServices')
                ? {
                    items: { 'regions/europe-central2': { backendServices: [computeObject(backendPath)] } },
                  }
                : computeObject(resource),
            );
            return true;
          }
          if (cliDiscovery(packet)) return true;
          const { req, url, input, result, res } = packet;
          if (req.method === 'POST' && url.searchParams.get('dryRun') === 'All') {
            res.setHeader('Warning', '299 - "fixture resource adjustment"');
            assert.equal(input.kind === 'List', false, 'Native admission must send individual workloads');
            admitted.push(input);
            if (fault === 'admission') {
              faultRequests++;
              res.statusCode = 403;
              result({
                apiVersion: 'v1',
                kind: 'Status',
                reason: 'Forbidden',
                message: 'fixture admission denied',
                code: 403,
              });
              return true;
            }
            const output = structuredClone(input);
            output.spec.template.spec.containers[0].resources.requests.cpu = '500m';
            output.metadata.namespace ??= `rivet-staging-${op.operationId}`;
            res.statusCode = 201;
            result(output);
            return true;
          }
          if (
            req.method === 'POST' &&
            input.kind === 'Deployment' &&
            input.metadata.name === 'release-gate-minio' &&
            ['lost-ack', 'interrupt'].includes(fault)
          ) {
            faultRequests++;
            nativeKubernetes({ ...packet, result: () => {} }); // Commit, then lose the reply.
            if (fault === 'lost-ack') res.destroy();
            else cancellation.abort(new Error('fixture interrupted dependency creation'));
            return true;
          }
          const handled = nativeKubernetes(packet);
          if (handled && req.method === 'POST' && input?.kind === 'Deployment') {
            const deployment = packet.objects.get(url.pathname + '/' + input.metadata.name);
            const set = [...packet.objects.values()].find(
              (r) =>
                r.kind === 'ReplicaSet' && r.metadata.ownerReferences?.some((o) => o.uid === deployment.metadata.uid),
            );
            for (const pod of packet.objects.values())
              if (pod.kind === 'Pod' && pod.metadata.labels?.['fixture-owner'] === deployment.metadata.name) {
                pod.metadata.ownerReferences = [
                  { controller: true, kind: 'ReplicaSet', name: set.metadata.name, uid: set.metadata.uid },
                ];
              }
          }
          return handled;
        } catch (error) {
          errors.push(error);
          packet.res.statusCode = 500;
          packet.result({ message: error.message });
          return true;
        }
      },
      deleted({ current, objects }) {
        if (current.kind === 'Namespace')
          for (const [key, value] of objects)
            if (value.metadata.namespace === current.metadata.name || value.kind === 'PersistentVolume')
              objects.delete(key);
      },
    });
    Object.assign(f.objects.get('/api/v1/namespaces/kube-system'), { apiVersion: 'v1', kind: 'Namespace' });
    const kubeconfig = path.join(folder, 'kubeconfig.json');
    await fs.writeFile(
      kubeconfig,
      JSON.stringify({
        apiVersion: 'v1',
        kind: 'Config',
        clusters: [{ name: 'fixture', cluster: { server: f.origin } }],
        users: [],
        contexts: [{ name: settings().context, context: { cluster: 'fixture' } }],
        'current-context': settings().context,
      }),
    );
    process.env.KUBECONFIG = kubeconfig;
    const tools = {
      node: process.version,
      kubectl: JSON.parse(
        (
          await run(process.env.RIVET_K8S_KUBECTL_BIN || 'kubectl', ['version', '--client', '-o', 'json'], {
            capture: true,
          })
        ).stdout,
      ).clientVersion.gitVersion,
      helm: (
        await run(process.env.RIVET_K8S_HELM_BIN || 'helm', ['version', '--short'], { capture: true })
      ).stdout.trim(),
    };
    assert.equal(tools.node, 'v24.22.1', 'Use the qualification Node version');
    assert.match(tools.kubectl, /^v1\.36\.6(?:\+\S+)?$/);
    assert.match(tools.helm, /^v3\.22\.1(?:\+\S+)?$/);
    const output = path.join(folder, 'package');
    await packageReusableStaging({
      settings: settings(),
      output,
      janitorImage: `registry.test/janitor@sha256:${digest}`,
      googleServiceAccount: 'janitor@isolated-staging.iam.gserviceaccount.com',
    });
    const { ReusableProviderGate, executeProviderPhase, withManagedGateSignal, waitForManagedGateCommands } =
      await import(pathToFileURL(path.join(output, 'driver/provider.mjs')));
    const gate = new ReusableProviderGate(op, settings(), f.state, folder);
    const app = await persistenceFixture(t, { headers: () => gate.probeHeaders, key: () => gate.secrets.rivetKey });
    gate.config.baseUrl = app.origin;
    const positive = (type) => ({ type, status: 'True', observedGeneration: 1 });
    f.store(
      `/apis/gateway.networking.k8s.io/v1/namespaces/${settings().gatewayNamespace}/gateways/${settings().gatewayName}`,
      {
        metadata: { uid: settings().gatewayUid, generation: 1 },
        spec: {
          listeners: [
            {
              name: 'https',
              protocol: 'HTTPS',
              port: 443,
              hostname: `*.${settings().domain}`,
              allowedRoutes: {
                namespaces: {
                  from: 'Selector',
                  selector: { matchLabels: { 'rivet.dev/qualification-route': 'true' } },
                },
              },
            },
          ],
        },
        status: {
          addresses: [{ type: 'IPAddress', value: '192.0.2.200' }],
          conditions: [positive('Programmed')],
          listeners: [{ name: 'https', conditions: [positive('Accepted'), positive('ResolvedRefs')] }],
        },
      },
    );
    f.store(`/apis/storage.k8s.io/v1/storageclasses/${settings().storageClassName}`, {
      metadata: { uid: 'storage-uid' },
      provisioner: 'pd.csi.storage.gke.io',
      reclaimPolicy: 'Delete',
    });
    f.store('/apis/metrics.k8s.io/v1beta1/nodes', {
      metadata: {},
      items: [{ timestamp: new Date().toISOString(), usage: { cpu: '10m', memory: '100Ki' } }],
    });
    // Only the provider-only observations are substituted. Rendering, admission,
    // dependency/route creation, Helm install/waits, auth, seeding and cleanup use
    // the shipped implementations. This cannot prove real TLS/NEG/CSI health.
    gate.verifySharedPrerequisites = () => inspectStagingPrerequisites(f.state, { verifyTls: async () => {} });
    gate.readyPublic = async () => {
      await gate.loadWorkflowKey();
      await gate.waitForDeveloperRoute(app.origin);
      await gate.verifyClientProvenance();
    };
    const cloud = stagingCloudReader(settings(), {
      token: async () => 'local-test-only',
      fetchImpl: (url, options) => {
        assert.equal(new URL(url).hostname, 'compute.googleapis.com');
        return fetch(`${f.origin}/fixture-compute${new URL(url).pathname}`, options);
      },
    });
    const steps = [];
    const phase = (name) =>
      executeProviderPhase({
        phase: name,
        operation: op,
        state: f.state,
        cloud,
        actor,
        gate,
        privateDirectory: folder,
        wait,
        step: async (name, action) => {
          steps.push(name);
          const started = Date.now();
          try {
            return await action();
          } finally {
            t.diagnostic(`${name}: ${Date.now() - started}ms`);
          }
        },
      });
    await f.state.arm(actor);
    const deadline = setTimeout(
      () => cancellation.abort(new Error(`Local preparation exceeded 30s at ${steps.at(-1)}`)),
      30000,
    );
    try {
      const preparing = withManagedGateSignal(cancellation.signal, () => phase('prepare'));
      if (fault === 'none') {
        await preparing;
        const execution = [...f.objects.values()].find(
          (resource) =>
            resource.kind === 'StatefulSet' &&
            resource.metadata.namespace === namespace &&
            resource.metadata.labels?.['app.kubernetes.io/component'] === 'execution' &&
            resource.spec.replicas > 0,
        );
        assert.equal(execution.spec.replicas, 3, 'Bootstrap must install the three-worker staging baseline');
        // Retained staging can still have the two-worker idle floor. Exercise
        // its preparation through the shipped method and native kubectl patch.
        execution.spec.replicas = 2;
        f.objects.delete(`/api/v1/namespaces/${namespace}/pods/${execution.metadata.name}-2`);
        await withManagedGateSignal(cancellation.signal, () => gate.prepareExecutionBaseline());
        assert.equal(
          f.objects.get(`/apis/apps/v1/namespaces/${namespace}/statefulsets/${execution.metadata.name}`).spec.replicas,
          3,
        );
        // Exercise the shipped apply override and real multi-kind kubectl read.
        // A pending frontend must not hold the template/controller prerequisite.
        await withManagedGateSignal(cancellation.signal, async () => {
          for (const resource of f.objects.values())
            if (
              resource.metadata.namespace === namespace &&
              resource.metadata.labels?.['app.kubernetes.io/component'] === 'proxy'
            ) {
              if (resource.kind === 'Deployment') resource.status.readyReplicas = resource.status.availableReplicas = 0;
              if (resource.kind === 'ReplicaSet') resource.status.readyReplicas = 0;
              if (resource.kind === 'Pod') resource.status.conditions = [{ type: 'Ready', status: 'False' }];
            }
          const values = gate.values(op.previous.images);
          await gate.apply(values, 'native-overlap-apply.json', { waitForReady: false });
          const resources = await gate.resources(values, 'native-overlap-resources');
          const workloads = resources
            .filter((r) => r.kind === 'StatefulSet')
            .map((r) => ({
              name: r.metadata.name,
              uid: f.objects.get(`/apis/apps/v1/namespaces/${namespace}/statefulsets/${r.metadata.name}`).metadata.uid,
            }));
          await waitForHaTemplateReadiness({
            kube: (...args) => gate.kube(...args),
            resources,
            workloads,
            release: gate.config.release,
            namespace,
            timeoutMs: 3000,
          });
          assert.ok(
            [...f.objects.values()].some(
              (r) =>
                r.kind === 'Deployment' &&
                r.metadata.labels?.['app.kubernetes.io/component'] === 'proxy' &&
                r.status.readyReplicas === 0,
            ),
          );
        });
      } else await assert.rejects(preparing, fault === 'interrupt' ? /interrupted dependency/ : /Command failed/);
    } catch (error) {
      t.diagnostic(JSON.stringify(f.requests.slice(-12).map((r) => ({ method: r.method, path: r.pathname }))));
      t.diagnostic(
        JSON.stringify(
          [...f.objects.values()]
            .filter((o) => o.kind === 'Deployment')
            .map((o) => ({
              name: o.metadata.name,
              generation: o.metadata.generation,
              replicas: o.spec.replicas,
              status: o.status,
            })),
        ),
      );
      throw error;
    } finally {
      clearTimeout(deadline);
      cancellation.abort();
      await gate.close();
      await waitForManagedGateCommands();
    }
    assert.equal(faultRequests, fault === 'none' ? 0 : 1, 'A failed/uncertain command must not be replayed');
    await phase('settle');
    await phase('cleanup');
    const cleanup = await phase('verifyCleanup');
    assert.equal(cleanup.uncertainWrites, 0);
    assert.equal((await f.state.read()).record.cleanupVerified, true);
    assert.ok(![...f.objects.values()].some((value) => value.metadata.namespace === namespace));
    assert.ok(f.objects.has(`/api/v1/namespaces/${settings().runnerNamespace}/pods/${actor.name}`));
    assert.ok(
      f.objects.has(
        `/apis/gateway.networking.k8s.io/v1/namespaces/${settings().gatewayNamespace}/gateways/${settings().gatewayName}`,
      ),
    );
    assert.deepEqual(errors, []);
    if (fault === 'none') {
      assert.ok(admitted.length >= 10, 'Both rendered releases must reach native admission');
      const summary = JSON.parse(await fs.readFile(path.join(folder, 'workload-admission-candidate.json')));
      assert.equal(summary.admitted[0].containers[0].resources.requests.cpu, '500m');
      assert.deepEqual(app.failures, []);
      assert.ok(app.requests.length >= 20);
      assert.ok(steps.includes('persistence') && steps.includes('inventory'));
      assert.equal(app.requests.filter((route) => route.endsWith('/web-app-auth')).length, 1);
    }
    t.diagnostic(
      JSON.stringify({ tools, nativeAdmissionWorkloads: admitted.length, steps, cleanup: cleanup.inventoryComplete }),
    );
  });
